import math

# Function to check if a number is prime
def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        if n % i == 0:
            return False
    return True

# Function to find three consecutive primes whose sum squared is 72361
def find_consecutive_primes_sum_squared(target):
    n = int(math.sqrt(target)) # Possible sum of the three consecutive primes
    for i in range(2, n):
        if is_prime(i):
            for j in range(i + 1, n):
                if is_prime(j):
                    for k in range(j + 1, n):
                        if is_prime(k):
                            if (i + j + k) ** 2 == target:
                                return [i, j, k]
    return None

# Target sum squared
target_sum_squared = 72361
